func TestAddIntervalClampsToTheMonthsLastDay(t *testing.T) {
	jan31 := time.Date(2026, 1, 31, 8, 15, 0, 0, time.UTC)
	if got := AddInterval(jan31, store.Monthly); !got.Equal(time.Date(2026, 2, 28, 8, 15, 0, 0, time.UTC)) {
		t.Errorf("Jan 31 + 1 month = %v, want Feb 28", got)
	}
	if got := AddInterval(time.Date(2028, 1, 31, 0, 0, 0, 0, time.UTC), store.Monthly); !got.Equal(time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Jan 31 2028 + 1 month = %v, want Feb 29", got)
	}
	if got := AddInterval(time.Date(2026, 2, 29, 0, 0, 0, 0, time.UTC), store.Yearly); !got.Equal(time.Date(2027, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Feb 29 2026 + 1 year = %v, want Feb 28 2027", got)
	}
}

func TestPeriodStartNeverDrifts(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 23, 59, 30, 0, time.UTC)
	want := []time.Time{
		time.Date(2026, 1, 31, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 2, 28, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 3, 31, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 4, 30, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 5, 31, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 6, 30, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 7, 31, 23, 59, 30, 0, time.UTC),
		time.Date(2026, 12, 31, 23, 59, 30, 0, time.UTC), // period 11
		time.Date(2027, 1, 31, 23, 59, 30, 0, time.UTC),  // period 12
	}
	for n, w := range want {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("period %d starts %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartYearlyFromLeapDay(t *testing.T) {
	anchor := time.Date(2028, 2, 29, 12, 0, 0, 0, time.UTC)
	for n, want := range map[int]time.Time{
		0: time.Date(2028, 2, 29, 12, 0, 0, 0, time.UTC),
		1: time.Date(2029, 2, 28, 12, 0, 0, 0, time.UTC),
		2: time.Date(2030, 2, 28, 12, 0, 0, 0, time.UTC),
		3: time.Date(2031, 2, 28, 12, 0, 0, 0, time.UTC),
		4: time.Date(2032, 2, 29, 12, 0, 0, 0, time.UTC),
	} {
		if got := PeriodStart(anchor, store.Yearly, n); !got.Equal(want) {
			t.Errorf("yearly period %d starts %v, want %v", n, got, want)
		}
	}
}

func TestPeriodStartIsUTC(t *testing.T) {
	anchor := time.Date(2026, 3, 1, 9, 0, 0, 0, time.FixedZone("CET", 3600))
	if got := PeriodStart(anchor, store.Monthly, 1); got.Location() != time.UTC || got.Hour() != 8 || got.Day() != 1 {
		t.Errorf("PeriodStart = %v, want 08:00 UTC on April 1", got)
	}
}

func TestNextPeriodOnSchedule(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	start, stop := NextPeriod(anchor, store.Monthly, time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC))
	if !start.Equal(time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)) || !stop.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) {
		t.Errorf("NextPeriod = %v, %v", start, stop)
	}
}

func TestNextPeriodRealignsADriftedEnd(t *testing.T) {
	// A period that ended on March 3 (drifted by an old AddDate) realigns onto the anchor's schedule at March 31.
	anchor := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	start, stop := NextPeriod(anchor, store.Monthly, time.Date(2026, 3, 3, 10, 0, 0, 0, time.UTC))
	if !start.Equal(time.Date(2026, 3, 3, 10, 0, 0, 0, time.UTC)) || !stop.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) {
		t.Errorf("NextPeriod = %v, %v", start, stop)
	}
}

func TestAnchorIsTrialEndWhenThereIsATrial(t *testing.T) {
	started := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	trialEnd := time.Date(2026, 2, 14, 10, 0, 0, 0, time.UTC)
	if got := Anchor(store.Subscription{StartedAt: started}); !got.Equal(started) {
		t.Errorf("Anchor = %v, want StartedAt", got)
	}
	if got := Anchor(store.Subscription{StartedAt: started, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
		t.Errorf("Anchor = %v, want TrialEnd", got)
	}
}
